<?php
session_start();
require_once __DIR__ . '/config/database.php';
if (!isset($_SESSION['user_id'])) { header('Location: login.php'); exit; }
$userId = (int) $_SESSION['user_id']; $notice = ''; $error = '';
if (empty($_SESSION['profile_csrf'])) $_SESSION['profile_csrf'] = bin2hex(random_bytes(24));
function profileValue($value) { return htmlspecialchars((string)$value, ENT_QUOTES, 'UTF-8'); }
function profilePhotoPath($id) { $files = glob(__DIR__ . '/uploads/profile/user-' . (int)$id . '.*'); return $files ? 'uploads/profile/' . basename($files[0]) : ''; }
if ($_SERVER['REQUEST_METHOD'] === 'POST') {
  if (!hash_equals($_SESSION['profile_csrf'], $_POST['csrf_token'] ?? '')) $error = 'Your form expired. Please try again.';
  else try {
    $action = $_POST['action'] ?? '';
    if ($action === 'details') {
      $first=trim($_POST['first_name']??''); $last=trim($_POST['last_name']??''); $email=trim($_POST['email']??'');
      if ($first===''||$last===''||!filter_var($email,FILTER_VALIDATE_EMAIL)) throw new RuntimeException('Enter a first name, last name, and valid email address.');
      $check=$pdo->prepare('SELECT id FROM users WHERE email=? AND id<>?'); $check->execute([$email,$userId]); if ($check->fetchColumn()) throw new RuntimeException('That email address is already in use.');
      $save=$pdo->prepare('UPDATE users SET first_name=?,last_name=?,email=? WHERE id=?'); $save->execute([$first,$last,$email,$userId]); $notice='Personal details saved.';
    } elseif ($action === 'password') {
      $row=$pdo->prepare('SELECT password_hash FROM users WHERE id=?'); $row->execute([$userId]);
      if (!password_verify($_POST['current_password']??'', (string)$row->fetchColumn())) throw new RuntimeException('Your current password is incorrect.');
      $new=$_POST['new_password']??''; if (strlen($new)<8||strlen($new)>72||$new!==($_POST['confirm_password']??'')) throw new RuntimeException('Use matching passwords between 8 and 72 characters.');
      $save=$pdo->prepare('UPDATE users SET password_hash=? WHERE id=?'); $save->execute([password_hash($new,PASSWORD_DEFAULT),$userId]); $notice='Password updated.';
    } elseif ($action === 'railroad') {
      $name=trim($_POST['railroad_name']??''); if ($name==='') throw new RuntimeException('Enter a railroad name.'); $save=$pdo->prepare('UPDATE railroads SET name=? WHERE user_id=?'); $save->execute([$name,$userId]); $notice='Railroad name updated.';
    } elseif ($action === 'photo') {
      $file=$_FILES['profile_photo']??null; if (!$file||$file['error']!==UPLOAD_ERR_OK||$file['size']>2*1024*1024) throw new RuntimeException('Choose an image smaller than 2 MB.');
      $type=(new finfo(FILEINFO_MIME_TYPE))->file($file['tmp_name']); $extensions=['image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp']; if (!isset($extensions[$type])) throw new RuntimeException('Use a JPG, PNG, or WebP image.');
      $directory=__DIR__.'/uploads/profile'; if (!is_dir($directory)&&!mkdir($directory,0755,true)) throw new RuntimeException('Unable to create the profile image folder.'); foreach (glob($directory.'/user-'.$userId.'.*') as $old) @unlink($old);
      if (!move_uploaded_file($file['tmp_name'],$directory.'/user-'.$userId.'.'.$extensions[$type])) throw new RuntimeException('Unable to save your profile picture.'); $notice='Profile picture updated.';
    }
  } catch (Throwable $exception) { $error=$exception->getMessage(); }
}
$user=$pdo->prepare('SELECT first_name,last_name,email FROM users WHERE id=?'); $user->execute([$userId]); $user=$user->fetch(PDO::FETCH_ASSOC);
$railroad=$pdo->prepare('SELECT name FROM railroads WHERE user_id=? LIMIT 1'); $railroad->execute([$userId]); $railroad=$railroad->fetch(PDO::FETCH_ASSOC); $photo=profilePhotoPath($userId); $plan='Free'; try {$sub=$pdo->prepare('SELECT plan_code FROM user_subscriptions WHERE user_id=? LIMIT 1');$sub->execute([$userId]);$plan=ucfirst((string)($sub->fetchColumn()?:'free'));}catch(Throwable $ignored){}
?>
