ght="96" style="object-fit:cover"><?php endif;?><form method="post" enctype="multipart/form-data"><input type="hidden" name="csrf_token" value="<?=profileValue($_SESSION['profile_csrf'])?>"><input type="hidden" name="action" value="photo"><label class="form-label">JPG, PNG, or WebP · 2 MB max</label><input class="form-control mb-3" type="file" name="profile_photo" accept="image/jpeg,image/png,image/webp" required><button class="btn btn-outline-primary">Upload picture</button></form></div></section><section class="card mb-4"><div class="card-body"><h2 class="h4">Your railroad</h2><form method="post"><input type="hidden" name="csrf_token" value="<?=profileValue($_SESSION['profile_csrf'])?>"><input type="hidden" name="action" value="railroad"><input class="form-control mb-3" name="railroad_name" required value="<?=profileValue($railroad['name']??'')?>"><button class="btn btn-outline-primary">Save railroad</button></form></div></section><section class="card"><div class="card-body"><h2 class="h4">Plan & billing</h2><p><strong><?=profileValue($plan)?></strong> plan</p><a class="btn btn-outline-primary" href="pricing.php">Manage plan</a><a class="btn btn-outline-danger mt-3" href="logout.php">Log out</a></div></section></div></div></main><?php include 'includes/footer.php'; ?>
